import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.NPCDialogue{EntityUniqueID: 258, ActionType: packet.NPCDialogueActionClose, Dialogue: "Hello",
# SceneName: "greeting", NPCName: "Guide", ActionJSON: "[]"}
CLOSE = bytes.fromhex("0201000000000000020548656c6c6f086772656574696e67054775696465025b5d")

# generated by gophertunnel b8bd735:
# packet.NPCDialogue{EntityUniqueID: 4294967296, ActionType: packet.NPCDialogueActionOpen}
EMPTY_STRINGS = bytes.fromhex("00000000010000000000000000")

GOLDENS = [
    pytest.param(
        v2225.NpcDialoguePacket(
            npc_id=258,
            npc_dialogue_action_type=v2225.NpcDialoguePacket.NpcDialogueActionType.CLOSE,
            dialogue="Hello",
            scene_name="greeting",
            npc_name="Guide",
            action_json="[]",
        ),
        CLOSE,
        id="close",
    ),
    pytest.param(
        v2225.NpcDialoguePacket(
            npc_id=4294967296,
            npc_dialogue_action_type=v2225.NpcDialoguePacket.NpcDialogueActionType.OPEN,
        ),
        EMPTY_STRINGS,
        id="empty-strings",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_npc_dialogue_is_packet_169(version):
    assert version.packets[169] is version.NpcDialoguePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_npc_dialogue_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_npc_dialogue_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
